    [50] = {
      beijing = 1391,
      dialog = 3,
      music = "05_Dream",
      renwu = "npc",
      sentence = "Meanwhile, a schoolmate of mine who had looked after me back in college had also received the invitation. He, too, was obliged by courtesy to accept it.",
